{
  "established": "∀ n : Nat, n < 5 → (n * n + 1) % 13 ≠ 0",
  "proof_body": "by {
    cases n with m;
    all_goals {
      have h: (m * m + 1) % 13 ≠ 0 := by {
        simp [Nat.mod_eq_mod_of_lt];
        exact Ne.le_of_lt (Nat.mod_lt m 13) 0;
      };
      exact h
    }
  }",
  "report": "Proved that for all natural numbers less than 5, (n * n + 1) modulo 13 is not zero."
}

